-- Página JUNO Media, versión 2 sobre la ya cargada (20, versión 1): actualiza los bloques 0-3 y añade el 4 y el 5. No borra nada.
begin;

update public.bloques set tipo = 'texto'::public.tipo_bloque, datos = $json${"estilo": "cabecera", "antetitulo": "JUNO Media y yo", "titulo": "Donde *empezó todo*", "imagen": "508f8ec8-b800-45cd-bf9a-013f1b276ef9", "texto": "JUNO Media es la productora con la que más trabajo y donde di mis primeros pasos. Desde entonces no hemos dejado de crear juntos: hoy, los proyectos que nacen allí los sacamos adelante Noelia Fluxà y yo.\n\nNos une una relación personal, artística y profesional. Y sigo siendo independiente: puedes trabajar conmigo directamente o, cuando el proyecto lo pide, con toda una productora detrás."}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 0;

update public.bloques set tipo = 'proceso'::public.tipo_bloque, datos = $json${"antetitulo": "Cómo trabajamos", "titulo": "Cercanía de autónomo, *respaldo de productora*", "pasos": [{"titulo": "Conmigo, directamente", "texto": "Me llamas, hablamos de tu idea y la levantamos juntos: rodaje, luz o montaje."}, {"titulo": "Un equipo pequeño", "texto": "Lo que entra en JUNO Media lo hacemos Noelia y yo. Trato directo y el mismo cuidado de principio a fin."}, {"titulo": "Una productora, si hace falta", "texto": "En los proyectos de gran envergadura, la producción queda en manos de una productora audiovisual y cinematográfica."}, {"titulo": "Tú eliges cómo", "texto": "Esa opción está siempre sobre la mesa. Y si veo que tu proyecto la necesita, te lo propongo yo."}]}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 1;

update public.bloques set tipo = 'cita'::public.tipo_bloque, datos = $json${"titulo": "Una productora detrás y *el mismo equipo* de siempre."}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 2;

update public.bloques set tipo = 'trabajos'::public.tipo_bloque, datos = $json${"antetitulo": "Proyectos con JUNO Media", "titulo": "Lo que hemos hecho *juntos*", "texto": "Videoclips, conciertos, eventos, cine y publicidad: buena parte de mi trabajo nace de esta colaboración.", "origen": "juno"}$json$::jsonb where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 3;

insert into public.bloques (pagina_id, orden, tipo, visible, datos) select (select id from public.paginas where slug = 'juno-media' and idioma = 'es'), 4, 'texto', true, $json${"estilo": "tarjeta", "antetitulo": "La productora", "titulo": "Conoce a *JUNO Media*", "imagen": "d8248ed7-bb85-48e0-8559-4a9779e5deb8", "texto": "Productora audiovisual y cinematográfica, a la medida de cada proyecto. Si buscas una producción completa, su web es un buen punto de partida.", "enlace": {"texto": "Visitar junomedia.es", "href": "https://junomedia.es"}}$json$::jsonb where not exists (select 1 from public.bloques where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 4);

insert into public.bloques (pagina_id, orden, tipo, visible, datos) select (select id from public.paginas where slug = 'juno-media' and idioma = 'es'), 5, 'llamada', true, coalesce((select x.datos from public.bloques x join public.paginas i on i.id = x.pagina_id where i.slug = 'inicio' and i.idioma = 'es' and x.tipo = 'llamada' order by x.orden limit 1), '{}'::jsonb) || $json${"titulo": "¿Tienes un proyecto en mente?", "texto": "Cuéntamelo. Te diré con sinceridad cómo lo veo y si conviene afrontarlo a solas o con JUNO Media."}$json$::jsonb where not exists (select 1 from public.bloques where pagina_id = (select id from public.paginas where slug = 'juno-media' and idioma = 'es') and orden = 5);

update public.paginas set seo_descripcion = $t$Trabajo en sinergia con JUNO Media: puedes contar conmigo directamente o, en los proyectos grandes, con la producción de una productora audiovisual detrás.$t$ where slug = 'juno-media' and idioma = 'es';

commit;
